/** Split "path::anchor" into its parts. */
export function parseRef(ref: AssociationRef): {
  path: string;
  anchor: string | null;
} {
  const idx = ref.indexOf("::");
  if (idx < 0) return { path: ref, anchor: null };
  return { path: ref.slice(0, idx), anchor: ref.slice(idx + 2) };
}
